import { graphql, useFragment } from "react-relay";
import UIIcon from "UIIcon.react";
import UIText from "UIText.react";
import { UIRow, UIColumn } from "UIStack.react";
import TextWithEntities from "TextWithEntities.react";

export default function ProfileContextItem({ item }) {
  const data = useFragment(
    graphql`
      fragment ProfileContextItem_item on ProfileContextItem {
        icon_name
        title {
          ...TextWithEntities_text
        }
        subtitle
      }
    `,
    item,
  );
  return (
    <UIRow gap={12} align="start" data-testid="profile-context-item">
      <UIIcon name={data.icon_name ?? "more"} size={20} />
      <UIColumn>
        <UIText>{data.title ? <TextWithEntities text={data.title} /> : null}</UIText>
        {data.subtitle ? (
          <UIText type="meta" color="secondary">
            {data.subtitle}
          </UIText>
        ) : null}
      </UIColumn>
    </UIRow>
  );
}
