// The profile's header: the cover photo, the avatar, the name with the
// friend facepile, the action buttons and the tab bar.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import { profileHeaderTokens } from "ComponentTokens.stylex";
import UIDivider from "UIDivider.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import ProfileCover from "ProfileCover.react";
import ProfileAvatarBlock from "ProfileAvatarBlock.react";
import ProfileNameBlock from "ProfileNameBlock.react";
import ProfileActions from "ProfileActions.react";
import ProfileTabs from "ProfileTabs.react";

const styles = stylex.create({
  header: { backgroundColor: colors.cardBackground, boxShadow: elevation.e1 },
  inner: { width: "100%", maxWidth: 1096, marginInline: "auto", paddingInline: 32, boxSizing: "border-box" },
  identity: { alignItems: "flex-end", gap: profileHeaderTokens.gap, paddingBottom: 16 },
  avatar: { marginTop: -32, flexShrink: 0 },
  name: { flexGrow: 1, paddingBottom: 8 },
  tabs: { paddingBottom: 0 },
});

export default function ProfileHeader({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileHeader_user on User {
        ...ProfileCover_user
        ...ProfileAvatarBlock_user
        ...ProfileNameBlock_user
        ...ProfileActions_user
        ...ProfileTabs_user
      }
    `,
    user,
  );
  return (
    <LoggingSurface name="profile_header">
      <UIColumn as="div" xstyle={styles.header}>
        <ProfileCover user={data} />
        <div {...stylex.props(styles.inner)}>
          <UIRow xstyle={styles.identity} align="end" wrap>
            <div {...stylex.props(styles.avatar)}>
              <ProfileAvatarBlock user={data} />
            </div>
            <div {...stylex.props(styles.name)}>
              <ProfileNameBlock user={data} />
            </div>
            <ProfileActions user={data} />
          </UIRow>
          <UIDivider />
          <div {...stylex.props(styles.tabs)}>
            <ProfileTabs user={data} />
          </div>
        </div>
      </UIColumn>
    </LoggingSurface>
  );
}
