import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import UIImage from "UIImage.react";
import UILink from "UILink.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  row: { gap: 8 },
  photo: { borderRadius: 8 },
});

export default function ProfileFeaturedPhotos({ photos }) {
  const data = useFragment(
    graphql`
      fragment ProfileFeaturedPhotos_photos on Photo @relay(plural: true) {
        id
        url
        accessibility_caption
        image(width: 112) {
          uri
        }
      }
    `,
    photos,
  );
  if (data.length === 0) {
    return null;
  }
  return (
    <UIRow xstyle={styles.row} data-testid="profile-featured-photos">
      {data.map((photo) => (
        <UILink key={photo.id} href={photo.url} label={photo.accessibility_caption ?? undefined} block>
          <UIImage src={photo.image?.uri} width={112} height={112} alt={photo.accessibility_caption ?? ""} xstyle={styles.photo} />
        </UILink>
      ))}
    </UIRow>
  );
}
