import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import UICard from "UICard.react";
import UIText from "UIText.react";
import UILink from "UILink.react";
import { UIRow } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import ProfilePhotoGrid from "ProfilePhotoGrid.react";

const styles = stylex.create({
  card: { padding: 16, marginBottom: 16 },
  header: { justifyContent: "space-between", paddingBottom: 12 },
});

export default function ProfilePhotosCard({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfilePhotosCard_user on User {
        vanity
        timeline_photos(first: 9) {
          ...ProfilePhotoGrid_photos
        }
      }
    `,
    user,
  );
  return (
    <LoggingSurface name="profile_photos">
      <UICard xstyle={styles.card} data-testid="profile-photos">
        <UIRow xstyle={styles.header}>
          <UIText type="headline3">{fbt("Photos", "title of the profile's photos card")}</UIText>
          <UILink href={`/${data.vanity}/photos`} color="link" label="See all photos">
            <UIText color="link">{fbt("See all photos", "link to the profile's photos")}</UIText>
          </UILink>
        </UIRow>
        {data.timeline_photos ? <ProfilePhotoGrid photos={data.timeline_photos} /> : null}
      </UICard>
    </LoggingSurface>
  );
}
