import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import UICard from "UICard.react";
import UIText from "UIText.react";
import UILink from "UILink.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import ProfileFriendTile from "ProfileFriendTile.react";

const styles = stylex.create({
  card: { padding: 16, marginBottom: 16 },
  header: { justifyContent: "space-between", paddingBottom: 12 },
  grid: { display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12 },
});

export default function ProfileFriendsCard({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileFriendsCard_user on User {
        vanity
        friends_count {
          text
        }
        friends(first: 9) {
          edges {
            node {
              id
            }
            ...ProfileFriendTile_edge
          }
        }
      }
    `,
    user,
  );
  return (
    <LoggingSurface name="profile_friends">
      <UICard xstyle={styles.card} data-testid="profile-friends">
        <UIRow xstyle={styles.header}>
          <UIColumn>
            <UIText type="headline3">{fbt("Friends", "title of the profile's friends card")}</UIText>
            <UIText type="meta" color="secondary">
              {data.friends_count?.text}
            </UIText>
          </UIColumn>
          <UILink href={`/${data.vanity}/friends`} label="See all friends">
            <UIText color="link">{fbt("See all friends", "link to the profile's friends")}</UIText>
          </UILink>
        </UIRow>
        <div {...stylex.props(styles.grid)}>
          {(data.friends?.edges ?? []).map((edge) => (edge?.node ? <ProfileFriendTile key={edge.node.id} edge={edge} /> : null))}
        </div>
      </UICard>
    </LoggingSurface>
  );
}
