// The intro card: the bio, the context items (work, education, places) and
// the featured photos.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import { profileIntroTokens } from "ComponentTokens.stylex";
import UICard from "UICard.react";
import UIText from "UIText.react";
import UIButton from "UIButton.react";
import { UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import TextWithEntities from "TextWithEntities.react";
import ProfileContextItem from "ProfileContextItem.react";
import ProfileFeaturedPhotos from "ProfileFeaturedPhotos.react";

const styles = stylex.create({
  card: { padding: 16, marginBottom: 16, gap: profileIntroTokens.gap },
  bio: { textAlign: "center" },
});

export default function ProfileIntroCard({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileIntroCard_user on User {
        profile_intro {
          bio {
            ...TextWithEntities_text
          }
          context_items {
            id
            ...ProfileContextItem_item
          }
          featured_photos {
            ...ProfileFeaturedPhotos_photos
          }
        }
      }
    `,
    user,
  );
  const intro = data.profile_intro;
  return (
    <LoggingSurface name="profile_intro">
      <UICard xstyle={styles.card} data-testid="profile-intro">
        <UIColumn gap={12}>
          <UIText type="headline3">{fbt("Intro", "title of the profile's intro card")}</UIText>
          {intro?.bio ? (
            <UIText xstyle={styles.bio} block>
              <TextWithEntities text={intro.bio} />
            </UIText>
          ) : null}
          <UIButton label={fbt("Edit bio", "button that edits the profile's bio")} use="secondary" />
          {(intro?.context_items ?? []).map((item) => (item ? <ProfileContextItem key={item.id} item={item} /> : null))}
          <UIButton label={fbt("Edit details", "button that edits the profile's details")} use="secondary" />
          <ProfileFeaturedPhotos photos={intro?.featured_photos ?? []} />
        </UIColumn>
      </UICard>
    </LoggingSurface>
  );
}
