import { graphql, useFragment } from "react-relay";
import UIButton from "UIButton.react";
import { UIRow } from "UIStack.react";

export default function ProfileActions({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileActions_user on User {
        profile_header_actions {
          key
          label
          icon_name
          is_primary
        }
      }
    `,
    user,
  );
  return (
    <UIRow gap={8} data-testid="profile-actions">
      {(data.profile_header_actions ?? []).map((action) =>
        action ? <UIButton key={action.key} label={action.label} icon={action.icon_name} use={action.is_primary ? "primary" : "secondary"} /> : null,
      )}
    </UIRow>
  );
}
