import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { profileTabTokens } from "ComponentTokens.stylex";
import UILink from "UILink.react";
import UIText from "UIText.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  bar: { gap: 4, minHeight: 60 },
  tab: { paddingInline: 16, paddingBlock: 16, borderRadius: profileTabTokens.radius, borderBottomWidth: 3, borderBottomStyle: "solid", borderBottomColor: "transparent" },
  selected: { borderBottomColor: colors.accent },
});

export default function ProfileTabs({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileTabs_user on User {
        profile_tabs {
          key
          title
          url
          is_selected
        }
      }
    `,
    user,
  );
  return (
    <UIRow as="nav" xstyle={styles.bar} data-testid="profile-tabs">
      {(data.profile_tabs ?? []).map((tab) =>
        tab ? (
          <UILink key={tab.key} href={tab.url} label={tab.title} xstyle={[styles.tab, tab.is_selected && styles.selected]}>
            <UIText weight="semibold" color={tab.is_selected ? "accent" : "secondary"}>
              {tab.title}
            </UIText>
          </UILink>
        ) : null,
      )}
    </UIRow>
  );
}
