// The "create post" box on a profile: like the home page's composer, with
// the profile owner's photo and a shorter row of actions.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import { colors, radii } from "BaseTokens.stylex";
import { composerInlineTokens } from "ComponentTokens.stylex";
import UICard from "UICard.react";
import UIAvatar from "UIAvatar.react";
import UIText from "UIText.react";
import UIButton from "UIButton.react";
import UIPressable from "UIPressable.react";
import UIDivider from "UIDivider.react";
import { UIRow } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";

const styles = stylex.create({
  card: { paddingTop: 12, paddingInline: 16, paddingBottom: 8, marginBottom: 16 },
  prompt: { flexGrow: 1, minHeight: 40, paddingInline: 12, borderRadius: radii.pill, backgroundColor: colors.inputBackground },
  actions: { paddingTop: 8, gap: composerInlineTokens.gap },
});

export default function ProfileComposer({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileComposer_user on User {
        short_name
        profile_picture(size: 40) {
          uri
        }
      }
    `,
    user,
  );
  return (
    <LoggingSurface name="profile_composer">
      <UICard xstyle={styles.card}>
        <UIRow gap={8}>
          <UIAvatar src={data.profile_picture?.uri} size={40} />
          <UIPressable label="Create a post" xstyle={styles.prompt} testid="profile-composer">
            <UIText color="secondary">{fbt("What's on your mind, " + fbt.param("name", data.short_name ?? "") + "?", "placeholder of the profile's post composer")}</UIText>
          </UIPressable>
        </UIRow>
        <UIDivider spaced />
        <UIRow xstyle={styles.actions}>
          <UIButton label={fbt("Live video", "composer action")} icon="video" use="flat" grow />
          <UIButton label={fbt("Photo/video", "composer action")} icon="photo" use="flat" grow />
          <UIButton label={fbt("Life event", "composer action")} icon="calendar" use="flat" grow />
        </UIRow>
      </UICard>
    </LoggingSurface>
  );
}
