import { graphql, useFragment } from "react-relay";
import UIText from "UIText.react";
import { UIColumn, UIRow } from "UIStack.react";
import VerifiedBadge from "VerifiedBadge.react";
import ProfileFriendFacepile from "ProfileFriendFacepile.react";

export default function ProfileNameBlock({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileNameBlock_user on User {
        name
        is_verified
        friends_count {
          text
        }
        ...ProfileFriendFacepile_user
      }
    `,
    user,
  );
  return (
    <UIColumn gap={4}>
      <UIRow>
        <UIText as="h1" type="headline1" data-testid="profile-name">
          {data.name}
        </UIText>
        {data.is_verified ? <VerifiedBadge /> : null}
      </UIRow>
      <UIText type="bodyLarge" color="secondary">
        {data.friends_count?.text}
      </UIText>
      <ProfileFriendFacepile user={data} />
    </UIColumn>
  );
}
