// The 3x3 grid of the profile's photos.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { photoGridTokens } from "ComponentTokens.stylex";
import UIImage from "UIImage.react";
import UILink from "UILink.react";

const styles = stylex.create({
  grid: { display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 4, borderRadius: 8, overflow: "hidden" },
  tile: { display: "block", aspectRatio: "1 / 1", overflow: "hidden", opacity: photoGridTokens.opacity },
});

export default function ProfilePhotoGrid({ photos }) {
  const data = useFragment(
    graphql`
      fragment ProfilePhotoGrid_photos on PhotoConnection {
        edges {
          node {
            id
            url
            accessibility_caption
            image(width: 220) {
              uri
            }
          }
        }
      }
    `,
    photos,
  );
  return (
    <div data-testid="profile-photo-grid" {...stylex.props(styles.grid)}>
      {(data.edges ?? []).map((edge) =>
        edge?.node ? (
          <UILink key={edge.node.id} href={edge.node.url} label={edge.node.accessibility_caption ?? undefined} block xstyle={styles.tile}>
            <UIImage src={edge.node.image?.uri} fill alt={edge.node.accessibility_caption ?? ""} />
          </UILink>
        ) : null,
      )}
    </div>
  );
}
