// One friend in the friends card: a square photo, the name and the mutual
// friends.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { friendGridTokens } from "ComponentTokens.stylex";
import UIImage from "UIImage.react";
import UILink from "UILink.react";
import UIText from "UIText.react";
import { UIColumn } from "UIStack.react";

const styles = stylex.create({
  tile: { gap: 4, minWidth: 0 },
  photo: { aspectRatio: "1 / 1", width: "100%", height: "auto", borderRadius: friendGridTokens.radius },
});

export default function ProfileFriendTile({ edge }) {
  const data = useFragment(
    graphql`
      fragment ProfileFriendTile_edge on UserEdge {
        mutual_text
        node {
          name
          url
          profile_picture(size: 160) {
            uri
          }
        }
      }
    `,
    edge,
  );
  const friend = data.node;
  return (
    <UIColumn xstyle={styles.tile} data-testid="profile-friend-tile">
      <UILink href={friend?.url} label={friend?.name ?? undefined} block>
        <UIImage src={friend?.profile_picture?.uri} width={160} height={160} alt={friend?.name ?? ""} xstyle={styles.photo} />
      </UILink>
      <UILink href={friend?.url} label={friend?.name ?? undefined} strong>
        <UIText type="meta" weight="semibold" numberOfLines={2}>
          {friend?.name}
        </UIText>
      </UILink>
      <UIText type="caption" color="secondary" numberOfLines={1}>
        {data.mutual_text}
      </UIText>
    </UIColumn>
  );
}
